 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next((grid[r][0] for r in range(h) if grid[r][0] != 0 and all(x == grid[r][0] for x in grid[r])), None)
    if sep is None:
        raise ValueError('no horizontal separator')
    row_bands = []
    start = 0
    for r in range(h):
        if all(x == sep for x in grid[r]):
            if start < r:
                row_bands.append((start, r))
            start = r + 1
    if start < h:
        row_bands.append((start, h))
    col_bands = []
    start = 0
    for c in range(w):
        if all(grid[r][c] == sep for r in range(h)):
            if start < c:
                col_bands.append((start, c))
            start = c + 1
    if start < w:
        col_bands.append((start, w))
    # The source motif is the first nonempty non-left panel; its color is replaced
    # with the identifying color in the leftmost panel of each row band.
    motif = None
    for r0, r1 in row_bands:
        for c0, c1 in col_bands[1:]:
            cells = [(r-r0, c-c0) for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] not in (0, sep)]
            if cells:
                motif = cells
                break
        if motif is not None:
            break
    if motif is None:
        raise ValueError('no motif')
    out = [[0 if x != sep else sep for x in row] for row in grid]
    for ri, (r0, r1) in enumerate(row_bands):
        color = next((grid[r][c] for r in range(r0, r1) for c in range(*col_bands[0]) if grid[r][c] not in (0, sep)), None)
        if color is None:
            continue
        for c0, c1 in col_bands:
            for dr, dc in motif:
                if r0 + dr < r1 and c0 + dc < c1:
                    out[r0 + dr][c0 + dc] = color
    return out
